// Phase 2: for every in_flight inbox row, check if the routed row has
// reached a state where Krish needs to look at it. If yes, flip the
// inbox row to needs_krish (the decisions_waiting view surfaces it).
const __helpers = this.helpers;
async function __req(opts) { return __helpers.httpRequest({ ...opts, returnFullResponse: false }); }
const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SB_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdvanBmZnNyeHliYnBiZHp6cnZzIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NjE3NzA2MywiZXhwIjoyMDkxNzUzMDYzfQ.QU6yz1uhH01U-Dcomd4DoPsGZmxYHh29K4bCOmfAKZc';
const H = { apikey: SB_KEY, Authorization: `Bearer ${SB_KEY}`, 'Content-Type': 'application/json' };
const Hmin = { ...H, 'Prefer': 'return=minimal' };

const inflight = await __req({
  method: 'GET',
  url: `${SUPA}/rest/v1/tasks_inbox?status=eq.in_flight&select=id,target_table,target_id,updated_at,raw_text,routed_to_agent`,
  headers: H, json: true,
});

let flipped = 0; let stale = 0;
const sevenDaysAgoMs = Date.now() - 7 * 86400000;

for (const r of (inflight || [])) {
  const target_table = r.target_table;
  const target_id    = r.target_id;
  if (!target_table || !target_id) continue;
  const refIso = r.updated_at;
  let needs = false;
  try {
    if (target_table === 'tasks') {
      const rs = await __req({ method: 'GET', url: `${SUPA}/rest/v1/tasks?id=eq.${target_id}&select=status,updated_at`, headers: H, json: true });
      const t = (rs || [])[0]; if (!t) continue;
      needs = ['waiting','pending-agatha-review','pending-review','blocked'].includes(t.status) && t.updated_at && t.updated_at > refIso;
    } else if (target_table === 'leads') {
      const rs = await __req({ method: 'GET', url: `${SUPA}/rest/v1/leads?id=eq.${target_id}&select=deep_enriched_at,promoted_task_id`, headers: H, json: true });
      const t = (rs || [])[0]; if (!t) continue;
      needs = !!t.deep_enriched_at && !t.promoted_task_id;
    } else if (target_table === 'visibility_targets') {
      const rs = await __req({ method: 'GET', url: `${SUPA}/rest/v1/visibility_targets?id=eq.${target_id}&select=status,deep_enriched_at`, headers: H, json: true });
      const t = (rs || [])[0]; if (!t) continue;
      needs = t.status === 'enriched' || !!t.deep_enriched_at;
    } else if (target_table === 'guests') {
      const rs = await __req({ method: 'GET', url: `${SUPA}/rest/v1/guests?id=eq.${target_id}&select=status,pitch_draft`, headers: H, json: true });
      const t = (rs || [])[0]; if (!t) continue;
      needs = t.status === 'enriched' || !!t.pitch_draft;
    } else if (target_table === 'content_ideas') {
      const rs = await __req({ method: 'GET', url: `${SUPA}/rest/v1/content_ideas?id=eq.${target_id}&select=state`, headers: H, json: true });
      const t = (rs || [])[0]; if (!t) continue;
      needs = ['review','seeded'].includes(t.state);
    } else if (target_table === 'bets') {
      const rs = await __req({ method: 'GET', url: `${SUPA}/rest/v1/bets?id=eq.${target_id}&select=status,est_mrr_impact_usd`, headers: H, json: true });
      const t = (rs || [])[0]; if (!t) continue;
      needs = t.status === 'live' && t.est_mrr_impact_usd == null;
    }
  } catch { needs = false; }

  // Time-out branch: 7 days in_flight without movement → mark failed.
  const ageMs = Date.now() - new Date(r.updated_at).getTime();
  if (!needs && ageMs > 7 * 86400000) {
    await __req({ method: 'PATCH', url: `${SUPA}/rest/v1/tasks_inbox?id=eq.${r.id}`, headers: Hmin, body: {
      status: 'failed', archive_reason: 'classifier_failed', archived_at: new Date().toISOString(),
    }, json: true }).catch(() => {});
    stale += 1;
    continue;
  }
  if (needs) {
    await __req({ method: 'PATCH', url: `${SUPA}/rest/v1/tasks_inbox?id=eq.${r.id}`, headers: Hmin, body: {
      status: 'needs_krish',
    }, json: true }).catch(() => {});
    flipped += 1;
  }
}

return [{ json: { ok: true, scanned: (inflight || []).length, flipped, stale, at: new Date().toISOString() } }];
